<section class="lux-page-top-hero lux-hero-tail lux-standard-hero lux-ms-hero lux-ms-hero-market relative flex items-center justify-center overflow-hidden" aria-labelledby="market-hero-title">
  <div class="lux-ms-hero-media" aria-hidden="true"></div><div class="absolute inset-0 lux-hero-fade-both"></div>
